```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::state_rw;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved grant: record every input in the shared store under `last-input`.
        state_rw::put("last-input", &feed_url);

        let now = wall_clock::now();

        // The one permitted fetch. Out-of-allowlist hosts trap at the boundary.
        let body = http_client::get(&feed_url);
        let fetched = u32::try_from(body.chars().count()).unwrap_or(u32::MAX);

        let notified = notifier::notify(&format!(
            "heartbeat: fetched {} chars from {}",
            fetched, feed_url
        ));

        // The contract requires notified == true on every output. A refused
        // notification must not produce an output, so trap instead.
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

